export interface Airport {
  iata: string;
  name: string;
  city: string;
  country: string;
  lat: number;
  lon: number;
}

let cache: Airport[] | null = null;

export function airports(): Airport[] {
  if (!cache) {
    cache = RAW.split('\n').map((line) => {
      const [iata, name, city, country, lat, lon] = line.split('|');
      return { iata, name, city, country, lat: Number(lat), lon: Number(lon) };
    });
  }
  return cache;
}
